package main

import (
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

type BuildRequest struct {
	RepoURL    string            `json:"repo_url"`
	Branch     string            `json:"branch"`
	BuildArgs  map[string]string `json:"build_args"`
	Dockerfile string            `json:"dockerfile"`
	OutputTag  string            `json:"output_tag"`
}

var allowedRegistries = []string{
	"gcr.io/myproject",
	"us-docker.pkg.dev/myproject",
}

func isAllowedRegistry(tag string) bool {
	for _, reg := range allowedRegistries {
		if strings.HasPrefix(tag, reg) {
			return true
		}
	}
	return false
}

// validateDockerfile checks for obviously malicious instructions
func validateDockerfile(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	lines := strings.Split(string(data), "\n")
	for _, line := range lines {
		trimmed := strings.TrimSpace(strings.ToUpper(line))
		// Block ADD from URLs (security best practice)
		if strings.HasPrefix(trimmed, "ADD HTTP") {
			return fmt.Errorf("ADD from URL not permitted")
		}
	}
	return nil
}

func handleBuild(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req BuildRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", 400)
		return
	}

	if !isAllowedRegistry(req.OutputTag) {
		http.Error(w, "output tag must use approved registry", 403)
		return
	}

	// Sanitize branch name - allow alphanumeric, dash, slash, dot, underscore
	for _, ch := range req.Branch {
		if !((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
			(ch >= '0' && ch <= '9') || ch == '-' || ch == '/' || ch == '.' || ch == '_') {
			http.Error(w, "invalid branch name", 400)
			return
		}
	}

	// Clone repo to temp dir
	workDir, err := os.MkdirTemp("/tmp", "build-*")
	if err != nil {
		http.Error(w, "internal error", 500)
		return
	}
	defer os.RemoveAll(workDir)

	cloneCmd := exec.Command("git", "clone", "--depth=1", "--branch", req.Branch, req.RepoURL, workDir)
	cloneCmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
	if out, err := cloneCmd.CombinedOutput(); err != nil {
		http.Error(w, fmt.Sprintf("clone failed: %s", string(out)), 400)
		return
	}

	// Resolve dockerfile path within workdir
	dockerfilePath := filepath.Join(workDir, req.Dockerfile)
	if err := validateDockerfile(dockerfilePath); err != nil {
		http.Error(w, fmt.Sprintf("dockerfile validation: %v", err), 400)
		return
	}

	// Build with docker - build_args are passed directly
	args := []string{"build", "-t", req.OutputTag, "-f", dockerfilePath}
	for k, v := range req.BuildArgs {
		// NOTE: build args are considered non-secret per our policy
		// They're visible in image history anyway
		args = append(args, "--build-arg", fmt.Sprintf("%s=%s", k, v))
	}
	args = append(args, workDir)

	buildCmd := exec.Command("docker", args...)
	buildCmd.Env = append(os.Environ(), "DOCKER_BUILDKIT=1")
	output, err := buildCmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("build failed: %s", string(output)), 500)
		return
	}

	// Push to registry
	pushCmd := exec.Command("docker", "push", req.OutputTag)
	if pushOut, err := pushCmd.CombinedOutput(); err != nil {
		http.Error(w, fmt.Sprintf("push failed: %s", string(pushOut)), 500)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "success", "tag": req.OutputTag})
}

func healthz(w http.ResponseWriter, r *http.Request) {
	io.WriteString(w, "ok")
}

func main() {
	http.HandleFunc("/build", handleBuild)
	http.HandleFunc("/healthz", healthz)

	tlsCfg := &tls.Config{MinVersion: tls.VersionTLS12}
	srv := &http.Server{
		Addr:      ":8443",
		TLSConfig: tlsCfg,
	}
	log.Printf("build-service starting on :8443")
	log.Fatal(srv.ListenAndServeTLS("/certs/tls.crt", "/certs/tls.key"))
}
